import { EventTypeSeverityLevel } from './event-type-severity-level';
/**
 * Configuration of an event type.
 */
export interface EventType {
    /**
     * A short description of the event type.
     */
    description?: string;
    /**
     * The display name of the event type.
     */
    displayName?: string;
    severityLevel?: EventTypeSeverityLevel;
    /**
     * The event type.
     */
    type?: string;
}
